{
  "technical_and_design_decisions": [
    "Rabbit batching will leverage Spring AMQP's BatchingRabbitTemplate for native batched message dispatch.",
    "Compression support will be refactored as a strategy pattern, exposing a CompressionStrategy interface that allows custom implementations to override the default codec.",
    "DIRT runtime DB-less mode will be implemented using Spring profiles and @Conditional configuration so existing installations are unaffected.",
    "RxJava processor module will define a core ReactiveProcessor contract that wraps RxJava's Observable/Flowable and adapts to the existing Spring XD MessageBus SPI.",
    "Gradle module support will be delivered as a reusable Gradle plugin (convention plugin) that applies Spring XD dependency management and the Spring Boot 'MODULE' layout.",
    "Performance benchmarks will be implemented using JMH (Java Microbenchmark Harness) integrated into the existing performance test module.",
    "HDFS-dataset acceptance tests will follow the conventions used by other XD modules' acceptance test suites and will be wired into the CI pipeline via the existing gradle acceptanceTest task.",
    "All features are designed to be backward-compatible: defaults preserve current behavior, and new opt-in configuration is additive."
  ],
  "assumptions": [
    "A senior developer with prior Spring XD / Spring Integration experience performs all work.",
    "The development environment runs Java 17+ (Spring Framework 6.0 baseline).",
    "The Spring XD source tree, RabbitMQ broker, and HDFS test cluster are available locally and in CI.",
    "Default batch parameters are: batchingEnabled = true, batchingSize = 100 (as noted in U5).",
    "U2 will be implemented using a workaround for the unresolved Spring Boot issue #2187 (module layout scoping) rather than blocked on it.",
    "The existing acceptance test framework used by other XD modules is available to be extended for hdfs-dataset.",
    "JMH or an equivalent microbenchmark framework is already wired into the performance module.",
    "Performance baseline runs from prior snapshots are accessible for comparison.",
    "The CI pipeline can be extended without infrastructure changes to pick up new acceptance tests.",
    "No external blocking dependencies (e.g., upstream Spring Boot release) are required to complete this increment."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "U1 - Rabbit Sink Batching Implementation",
      "activity_description": "Add batchingEnabled/batchingSize options to the Rabbit sink module, switch to BatchingRabbitTemplate, and ensure messages are buffered and flushed per configured size or interval. Update option metadata and parser wiring."
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - Rabbit Sink Batching Tests",
      "activity_description": "Author unit and integration tests verifying default-off behavior, batched dispatch at the configured size, and error handling on partial batch failure."
    },
    {
      "activity_id": "A3",
      "activity_name": "U2 - Gradle Module Build Investigation",
      "activity_description": "Investigate Spring Boot issue #2187 status, determine a workable convention for the MODULE layout, and design the Gradle convention plugin API surface."
    },
    {
      "activity_id": "A4",
      "activity_name": "U2 - Gradle Module Build Implementation",
      "activity_description": "Implement the convention Gradle plugin: declare Spring XD dependencies as 'provided', apply the Spring Boot plugin with MODULE layout, and ship a sample module project demonstrating usage. Include tests for the plugin and the sample."
    },
    {
      "activity_id": "A5",
      "activity_name": "U3 - HDFS-Dataset Acceptance Tests",
      "activity_description": "Design acceptance test scenarios for the hdfs-dataset module (writes, rollovers, partition paths, schema handling), implement them using the XD acceptance test framework, and wire the suite into the CI gradle build so it runs on every build."
    },
    {
      "activity_id": "A6",
      "activity_name": "U4 - Compression Extension Support",
      "activity_description": "Introduce a CompressionStrategy SPI, refactor the existing compression codec to be the default implementation, expose configuration to override the strategy, and add unit tests for the extension point and the default behavior."
    },
    {
      "activity_id": "A7",
      "activity_name": "U5 - Rabbit Batching Benchmarks",
      "activity_description": "Set up JMH benchmarks for the Rabbit sink with batchingEnabled=true and batchingSize=100, run them against the baseline environment, and record results for comparison with previous snapshots. Include one sweep at a varied size for granular reporting."
    },
    {
      "activity_id": "A8",
      "activity_name": "U6 - Rabbit Compression Benchmarks",
      "activity_description": "Set up JMH benchmarks for the Rabbit sink with compression enabled, run them, and record results for comparison with previous baseline snapshots."
    },
    {
      "activity_id": "A9",
      "activity_name": "U7 - DIRT Runtime DB-less Support",
      "activity_description": "Introduce a configuration option (and Spring profile) to disable the database/Redis requirements, conditionally exclude the JDBC/Redis-backed beans via @Conditional, and verify stream deployment and processing still work end-to-end. Add unit and integration tests."
    },
    {
      "activity_id": "A10",
      "activity_name": "U8 - RxJava Processor Module",
      "activity_description": "Define the core ReactiveProcessor contract, implement a processor module that consumes/produces via RxJava Observables, adapt the contract to the existing XD MessageBus SPI, and provide unit and integration tests plus usage documentation."
    },
    {
      "activity_id": "A11",
      "activity_name": "Cross-feature Integration Testing",
      "activity_description": "Run a full integration suite combining the new Rabbit batching, compression, DIRT DB-less, and RxJava features to verify they do not regress one another; triage and fix any interactions."
    },
    {
      "activity_id": "A12",
      "activity_name": "Documentation Updates",
      "activity_description": "Update reference documentation, option metadata tables, the RxJava module guide, the Gradle module author guide, and the performance benchmark notes. Add release notes summarizing new options."
    },
    {
      "activity_id": "A13",
      "activity_name": "Code Review and Final Polish",
      "activity_description": "Self-review all changes, address inline review comments, ensure consistent style and logging, and finalize the increment for merge."
    }
  ],
  "reported_total": {
    "most_likely_effort": 164
  }
}
```

